// src/components/onboarding/AuthScreen.tsx

import React, { useState } from 'react';
import { Button } from '../common/Button';
import { Input } from '../common/Input';
import { Mail, Apple, ArrowLeft } from 'lucide-react';

interface AuthScreenProps {
  onAuth: (provider: 'apple' | 'google' | 'email', email?: string) => void;
  onBack: () => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onAuth, onBack }) => {
  const [showEmailForm, setShowEmailForm] = useState(false);
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSocialAuth = async (provider: 'apple' | 'google') => {
    setIsLoading(true);
    await new Promise(resolve => setTimeout(resolve, 800));
    onAuth(provider);
  };

  const handleEmailAuth = async () => {
    if (!email.trim()) return;
    setIsLoading(true);
    await new Promise(resolve => setTimeout(resolve, 800));
    onAuth('email', email);
  };

  return (
    <div className="min-h-screen bg-white flex flex-col">
      {/* Header */}
      <div className="p-6">
        <button
          onClick={onBack}
          className="p-2 -ml-2 hover:bg-dark-50 rounded-xl transition-colors"
        >
          <ArrowLeft className="w-6 h-6 text-dark-700" />
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 flex items-center justify-center px-6">
        <div className="w-full max-w-sm">
          {!showEmailForm ? (
            <div className="space-y-6 animate-fade-in">
              <div className="text-center mb-8">
                <h1 className="text-3xl font-bold text-dark-900 mb-2">
                  Welcome
                </h1>
                <p className="text-dark-600">
                  Choose a method to continue
                </p>
              </div>

              {/* Social Auth Buttons */}
              <div className="space-y-3">
                <Button
                  onClick={() => handleSocialAuth('apple')}
                  disabled={isLoading}
                  fullWidth
                  size="lg"
                  className="bg-dark-900 text-white hover:bg-dark-800"
                  icon={<Apple className="w-5 h-5" />}
                >
                  Continue with Apple
                </Button>

                <Button
                  onClick={() => handleSocialAuth('google')}
                  disabled={isLoading}
                  fullWidth
                  size="lg"
                  variant="secondary"
                  className="border border-dark-200"
                  icon={
                    <svg className="w-5 h-5" viewBox="0 0 24 24">
                      <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                      <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                      <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                      <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                    </svg>
                  }
                >
                  Continue with Google
                </Button>

                <div className="relative py-4">
                  <div className="absolute inset-0 flex items-center">
                    <div className="w-full border-t border-dark-200"></div>
                  </div>
                  <div className="relative flex justify-center text-sm">
                    <span className="px-4 bg-white text-dark-500">or</span>
                  </div>
                </div>

                <Button
                  onClick={() => setShowEmailForm(true)}
                  disabled={isLoading}
                  fullWidth
                  size="lg"
                  variant="ghost"
                  className="border border-dark-200"
                  icon={<Mail className="w-5 h-5" />}
                >
                  Continue with Email
                </Button>
              </div>

              <p className="text-xs text-center text-dark-500 mt-8 leading-relaxed">
                By continuing, you agree to our{' '}
                <a href="#" className="text-primary-600 hover:underline">Terms</a>
                {' & '}
                <a href="#" className="text-primary-600 hover:underline">Privacy Policy</a>
              </p>
            </div>
          ) : (
            <div className="space-y-6 animate-fade-in">
              <div className="text-center mb-8">
                <h2 className="text-2xl font-bold text-dark-900 mb-2">
                  Sign in with Email
                </h2>
                <p className="text-dark-600">
                  We'll send you a magic link
                </p>
              </div>

              <Input
                type="email"
                placeholder="your@email.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                icon={<Mail className="w-5 h-5" />}
                disabled={isLoading}
                className="text-lg"
              />

              <div className="space-y-3">
                <Button
                  onClick={handleEmailAuth}
                  disabled={isLoading || !email.trim()}
                  fullWidth
                  size="lg"
                  className="bg-primary-600 hover:bg-primary-700 text-white"
                >
                  {isLoading ? 'Sending...' : 'Send Magic Link'}
                </Button>

                <button
                  onClick={() => setShowEmailForm(false)}
                  disabled={isLoading}
                  className="w-full text-dark-600 text-sm hover:text-dark-900 transition-colors py-2"
                >
                  ← Back to options
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};
